import heapq
from collections import Counter


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    choices = [[-1] + list(rows[name]) for name in names]
    best_vector = None
    best_versions = None

    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name, -1) < bounds[0] or
               selected.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(version != -1 and
               (version in blocked.get(name, []) or
                (name in pins and pins[name] != version))
               for name, version in selected.items()):
            continue

        edges = {name: [] for name, version in selected.items() if version != -1}
        valid = True
        for name in edges:
            row = rows[name][selected[name]]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                version = selected.get(target, -1)
                if version < dep["min"] or version > dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        installed = {name for name, version in selected.items() if version != -1}
        if reachable != installed:
            continue

        finished, active = set(), set()
        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in edges):
            continue

        vector = tuple(selected[name] for name in names)
        if best_vector is None or ((vector > best_vector) if preference == "maximum"
                                   else (vector < best_vector)):
            best_vector = vector
            best_versions = {name: version for name, version in selected.items()
                             if version != -1}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_01(data):
